HTML = "<!doctype html><html lang=\"ko\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>GEXOption · 소라 AI</title><style>\n:root{color-scheme:dark;font-family:system-ui,sans-serif;background:#0b1422;color:#edf4ff}*{box-sizing:border-box}body{margin:0}header{padding:10px 14px;border-bottom:1px solid #34445c;display:flex;align-items:center;justify-content:space-between}h1{font-size:19px;margin:0}.tiny{color:#a9bcd6;font-size:12px}.shell{max-width:1200px;margin:auto}.layout{display:grid;grid-template-columns:260px minmax(0,1fr);gap:12px;padding:12px}.sidebar,.workspace{border:1px solid #34445c;border-radius:12px;background:#132139}.sidebar{padding:12px;max-height:85dvh;overflow:auto}.sidebar button{width:100%;margin:3px 0;text-align:left}.workspace{display:flex;flex-direction:column;height:calc(100dvh - 80px);min-height:560px;overflow:hidden}.toolbar{display:flex;gap:8px;align-items:center;padding:9px;border-bottom:1px solid #34445c}select,button,input{font:inherit;color:#ecf3ff;background:#263952;border:1px solid #49627f;border-radius:9px;padding:10px}button{cursor:pointer}button:disabled{opacity:.5}.toolbar select{max-width:60%;min-width:0}.chart{flex:1;min-height:0;padding:10px;display:flex;flex-direction:column;gap:8px;border-bottom:1px solid #34445c}.plot{flex:1;min-height:70px;width:100%;border:1px solid #30425c;border-radius:9px;background:#0d1b2c}svg{width:100%;height:100%}.chat{flex:2;min-height:0;display:flex;flex-direction:column}.messages{flex:1;overflow:auto;padding:12px;display:flex;flex-direction:column;gap:10px}.bubble{max-width:89%;padding:10px 12px;border-radius:12px;background:#293a52;white-space:pre-wrap;line-height:1.5;font-size:14px}.bubble.user{align-self:flex-end;background:#166452}.entry{display:flex;gap:7px;padding:9px;border-top:1px solid #34445c}.entry input{flex:1;min-width:0}.muted{color:#afc0d6}.warning{color:#ffd590}.hidden{display:none}.flag{font-size:12px;background:#283c56;padding:5px 8px;border-radius:10px}.search{width:100%;margin-bottom:8px}@media(max-width:680px){header{padding:8px 12px}.layout{display:block;padding:0}.sidebar{display:none}.workspace{height:calc(100dvh - 51px);min-height:0;border-radius:0;border:0}.chart{flex:1}.chat{flex:2}.toolbar{padding:6px}.chart{padding:7px}.bubble{font-size:14px}}\n\n.tv-wrap{flex:1;min-height:160px;width:100%;background:#FFFFFF;overflow:hidden;border-radius:9px}.tv-wrap .tradingview-widget-container,.tv-wrap .tradingview-widget-container__widget{height:100%;width:100%}.tv-credit{font-size:11px;color:#a9bcd6}.tv-credit a{color:#83d6c5;text-decoration:underline}\n\n/* SORA light classroom palette: preserve markup and mobile layout. */\n:root{color-scheme:light!important;background:#FFFFFF!important;color:#182638!important}\nbody{background:#FFFFFF!important;color:#182638!important}\nheader,.sidebar,.workspace,.toolbar,.chart,.chat,.messages,.entry{background:#FFFFFF!important;color:#182638!important;border-color:#E1E7EE!important}\n.sidebar,.workspace{box-shadow:none!important}\nselect,button,input{background:#FFFFFF!important;color:#182638!important;border-color:#C9D4E0!important}\nbutton:hover{background:#EEF6F4!important}\n.bubble{background:#F0F4F8!important;color:#182638!important}\n.bubble.user{background:#DBF5ED!important;color:#123B32!important}\n.tiny,.muted,.tv-credit{color:#516277!important}\n.flag{background:#EAF4F1!important;color:#216654!important}\n.plot,.tv-wrap{background:#FFFFFF!important;border-color:#DCE5ED!important}\n.tv-credit a{color:#086E67!important}\n\n/* Gentle grade-tinted LEADER 40 stock list, white classroom theme. */\n#stockList button{border:1px solid #E5EAF1!important;border-radius:9px;margin:4px 0!important;padding:10px 12px!important;background:#F7F9FC!important;color:#243449!important;transition:background .15s,border-color .15s;}\n#stockList button:nth-child(4n + 1){background:#F0F7FF!important;border-color:#DCE9FA!important}\n#stockList button:nth-child(4n + 2){background:#F0FAF7!important;border-color:#D9F0E8!important}\n#stockList button:nth-child(4n + 3){background:#F7F4FF!important;border-color:#E7DFF8!important}\n#stockList button:nth-child(4n){background:#FFF9EF!important;border-color:#F4EADB!important}\n#stockList button:hover,#stockList button:focus-visible{background:#DFEEFF!important;border-color:#87B8E7!important}\n#stockList button[aria-pressed=\"true\"]{background:#DCEFEA!important;border:2px solid #22A987!important;color:#0D594A!important;font-weight:700}\n\n/* Price-direction colors, only after confirmed two-session close data. */\n#stockList button[data-trend=\"up\"]{background:#E7F6EE!important;border-color:#B8E2C9!important;color:#185E3B!important}\n#stockList button[data-trend=\"down\"]{background:#FDEBEC!important;border-color:#F3C5CA!important;color:#94363F!important}\n#stockList button[data-trend=\"flat\"]{background:#F3F5F7!important;border-color:#DDE3E9!important;color:#435367!important}\n#stockList button[data-trend=\"unknown\"]{background:#FFFFFF!important;border-color:#DDE3E9!important;color:#435367!important}\n#stockList button[aria-pressed=\"true\"]{outline:2px solid #22A987!important;outline-offset:-2px;font-weight:700}\n#stockList .daily-move{display:block;font-size:11px;margin-top:2px;opacity:.85}\n\n/* Enlarged TradingView teaching chart: compact controls and readable candles. */\n.workspace .toolbar{padding:6px 10px!important;min-height:44px;gap:8px;border-bottom:0!important}\n.workspace .toolbar select{padding:5px 9px!important;font-size:12px!important;max-width:180px}\n.workspace .chart{flex:1.28!important;min-height:252px!important;padding:4px 10px 8px!important;gap:4px!important}\n.workspace .tv-wrap{min-height:208px!important;border:1px solid #E1E7EE!important}\n.workspace .chat{flex:1!important;min-height:180px}\n.workspace .chart .tiny{font-size:10px!important}\n@media(max-width:680px){.workspace .chart{min-height:224px!important;flex:1!important}.workspace .tv-wrap{min-height:176px!important}.workspace .toolbar{padding:5px 7px!important}.workspace .chat{flex:1!important}}\n</style></head><body><div class=\"shell\"><header><h1>GEXOption · 소라 AI</h1><span class=\"flag\">LEADER 40 · 교육용 베타</span></header><div class=\"layout\"><aside class=\"sidebar\"><strong>LEADER 40</strong><p class=\"tiny\">초기 후보 · 등급 검증 전</p><input id=\"search\" class=\"search\" placeholder=\"종목 검색\" aria-label=\"종목 검색\"><div id=\"stockList\"></div></aside><main class=\"workspace\"><section class=\"chart\" aria-label=\"차트\"><div class=\"toolbar\"><label for=\"ticker\" class=\"tiny\">종목</label><select id=\"ticker\" aria-label=\"종목 선택\"></select><select id=\"tf\" aria-label=\"차트 주기\"><option value=\"1d\">일봉</option><option value=\"30m\">30분봉</option><option value=\"5m\">5분봉</option></select></div><div class=\"tiny\" id=\"chartStatus\">차트 조회 전</div><div class=\"tv-wrap\" id=\"tvWrap\" aria-label=\"TradingView 주식 차트\"><div id=\"tvChart\" class=\"tradingview-widget-container\"></div></div><div class=\"tiny\"><span class=\"tv-credit\">TradingView 무료 차트 · 시세 지연 가능 · Wall은 별도 API 필요 · <a href=\"https://www.tradingview.com/\" target=\"_blank\" rel=\"noopener noreferrer\">TradingView</a></span></div></section><section class=\"chat\" aria-label=\"소라 대화\"><div class=\"messages\" id=\"messages\" role=\"log\" aria-live=\"polite\"></div><form id=\"chatForm\" class=\"entry\"><input id=\"question\" maxlength=\"1200\" placeholder=\"소라에게 차트 분석 질문...\" autocomplete=\"off\" aria-label=\"질문\"><button id=\"send\" type=\"submit\">전송</button></form></section></main></div></div><script>\n\"use strict\";\nconst GROUPS={\"A+\":[\"NVDA\",\"MSFT\",\"GOOGL\",\"AMZN\",\"META\",\"TSLA\",\"PLTR\",\"AVGO\",\"GEV\",\"TSM\"],\"A\":[\"MU\",\"CRDO\",\"ANET\",\"VRT\",\"ETN\",\"FIX\",\"APP\",\"LITE\",\"DELL\",\"NFLX\"],\"B\":[\"SNDK\",\"STX\",\"WDC\",\"INTC\",\"MXL\",\"MRVL\",\"COHR\",\"VIAV\",\"CIEN\",\"TER\"],\"C\":[\"IREN\",\"NBIS\",\"CIFR\",\"CLSK\",\"RKLB\",\"OKLO\",\"SMR\",\"RGTI\",\"QBTS\",\"SOUN\"]};\nconst $=id=>document.getElementById(id);const dailyMoves=new Map();const conversations=new Map();let chosen=\"AMZN\",pending=false,chartSeq=0;\nfunction add(role,text){const div=document.createElement(\"div\");div.className=\"bubble\"+(role===\"user\"?\" user\":\"\");div.textContent=(role===\"user\"?\"나: \":\"소라: \")+text;$(\"messages\").append(div);$(\"messages\").scrollTop=$(\"messages\").scrollHeight}\nfunction paintChat(){const items=conversations.get(chosen)||[];$(\"messages\").replaceChildren();if(!items.length)add(\"assistant\",chosen+\" 분석 준비됐습니다. 먼저 일봉 기울기와 위치를 확인하고, 30분봉 진입 구조 또는 5분봉 CORE 헤지 분석을 설명하겠습니다. 현재 데이터 연결 전에는 실시간 가격을 단정하지 않습니다.\");else items.forEach(x=>add(x.role,x.content))}\nfunction renderStockList(){const root=$(\"stockList\");root.replaceChildren();const q=$(\"search\").value.trim().toUpperCase();for(const [grade,names] of Object.entries(GROUPS)){for(const name of names.filter(s=>s.includes(q))){const b=document.createElement(\"button\");b.textContent=grade+\" · \"+name;const info=dailyMoves.get(name);b.dataset.trend=info?info.trend:\"unknown\";const sub=document.createElement(\"span\");sub.className=\"daily-move\";sub.textContent=info?info.text:\"최근 일봉 · 미확인\";b.append(sub);b.setAttribute(\"aria-pressed\",String(name===chosen));b.addEventListener(\"click\",()=>choose(name));root.append(b)}}}\nfunction choose(ticker){if(pending)return;chosen=ticker;$(\"ticker\").value=ticker;renderStockList();paintChat();updateChart()}\nconst all=Object.entries(GROUPS).flatMap(([grade,names])=>names.map(symbol=>({grade,symbol})));for(const x of all){const opt=document.createElement(\"option\");opt.value=x.symbol;opt.textContent=x.symbol+\" · \"+x.grade;$(\"ticker\").append(opt)}\n\n// Previous two reported daily closes, not a real-time quote. Missing data stays neutral.\nasync function checkDailyMove(ticker){try{const res=await fetch(\"/api/search?mode=daily_bars&ticker=\"+encodeURIComponent(ticker),{credentials:\"same-origin\",cache:\"no-store\"});if(!res.ok)throw Error(\"HTTP \"+res.status);const j=await res.json();const bars=Array.isArray(j.bars)?j.bars.filter(x=>Number.isFinite(Number(x.close))&&Number(x.close)>0&&/^\\\\d{4}-\\\\d{2}-\\\\d{2}$/.test(x.time||\"\")):[];if(bars.length<2)throw Error(\"missing bars\");const prev=bars[bars.length-2],last=bars[bars.length-1];const age=(Date.now()-Date.parse(last.time+\"T00:00:00Z\"))/86400000;if(age< -1||age>7)throw Error(\"stale data\");const pct=(Number(last.close)/Number(prev.close)-1)*100;if(!Number.isFinite(pct))throw Error(\"invalid change\");const trend=Math.abs(pct)<0.005?\"flat\":pct>0?\"up\":\"down\";dailyMoves.set(ticker,{trend,text:\"최근 일봉 \"+last.time+\" · \"+(pct>0?\"▲ +\":pct<0?\"▼ \":\"— \")+pct.toFixed(2)+\"%\"});}catch(err){dailyMoves.set(ticker,{trend:\"unknown\",text:\"최근 일봉 · 미확인\"});}renderStockList()}\nasync function loadDailyMoves(){const universe=all.map(x=>x.symbol);let pos=0;const worker=async()=>{while(pos<universe.length){const ticker=universe[pos++];await checkDailyMove(ticker)}};await Promise.all([worker(),worker()])}\nfunction trace(bars){const svg=$(\"plot\");svg.replaceChildren();const last=bars.slice(-55);if(last.length<2)throw Error(\"가격 데이터 부족\");const ys=last.map(x=>Number(x.close));if(ys.some(x=>!Number.isFinite(x)))throw Error(\"가격 데이터 오류\");const lo=Math.min(...ys),hi=Math.max(...ys),span=hi-lo||1;const pts=ys.map((v,i)=>[8+(i/(ys.length-1))*304,100-(v-lo)/span*85]);const poly=document.createElementNS(\"http://www.w3.org/2000/svg\",\"polyline\");poly.setAttribute(\"points\",pts.map(v=>v.join(\",\")).join(\" \"));poly.setAttribute(\"fill\",\"none\");poly.setAttribute(\"stroke\",\"#5be0ad\");poly.setAttribute(\"stroke-width\",\"2\");svg.append(poly)}\nfunction updateChart(){const ticker=chosen,tf=$(\"tf\").value,seq=++chartSeq;const exchange=([\"TSM\",\"GEV\",\"ETN\",\"FIX\",\"APP\",\"DELL\",\"SNDK\",\"STX\",\"WDC\",\"CIEN\",\"VRT\",\"LITE\",\"RGTI\",\"QBTS\"].includes(ticker)?\"NYSE\":\"NASDAQ\");const symbol=exchange+\":\"+ticker;const interval=({\"1d\":\"D\",\"30m\":\"30\",\"5m\":\"5\"})[tf]||\"D\";$(\"chartStatus\").textContent=ticker+\" · \"+tf+\" · TradingView 차트 (표시 시세 지연 가능, 소라 AI와 데이터 자동 동기화 아님)\";const root=$(\"tvChart\");root.replaceChildren();const host=document.createElement(\"div\");host.className=\"tradingview-widget-container__widget\";root.append(host);const script=document.createElement(\"script\");script.type=\"text/javascript\";script.async=true;script.src=\"https://s3.tradingview.com/external-embedding/embed-widget-advanced-chart.js\";script.textContent=JSON.stringify({autosize:true,symbol: symbol,interval:interval,timezone:\"America/New_York\",theme:\"light\",style:\"1\",locale:\"kr\",allow_symbol_change:false,hide_top_toolbar:false,hide_legend:false,save_image:false,calendar:false,support_host:\"https://www.tradingview.com\"});script.onerror=()=>{if(seq===chartSeq)$(\"chartStatus\").textContent=ticker+\" · TradingView 로딩 실패 (연결 또는 브라우저 차단 확인)\"};root.append(script)}\nasync function submit(e){e.preventDefault();if(pending)return;const text=$(\"question\").value.trim();if(!text)return;pending=true;$(\"send\").disabled=true;const t=chosen;const history=(conversations.get(t)||[]).slice(-8);const full=conversations.get(t)||[];full.push({role:\"user\",content:text});conversations.set(t,full);add(\"user\",text);$(\"question\").value=\"\";try{const r=await fetch(\"/api/sora_chat\",{method:\"POST\",credentials:\"same-origin\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify({ticker:t,message:text,history})});const j=await r.json();if(!r.ok)throw Error(j.error||\"응답 실패\");const answer=String(j.answer||\"\").trim();if(!answer)throw Error(\"빈 응답\");full.push({role:\"assistant\",content:answer});if(chosen===t)add(\"assistant\",answer);}catch(err){if(chosen===t)add(\"assistant\",\"연결 오류: \"+err.message+\" · AI 연결을 먼저 확인해 주세요.\");}finally{pending=false;$(\"send\").disabled=false}}\n$(\"ticker\").addEventListener(\"change\",e=>choose(e.target.value));$(\"tf\").addEventListener(\"change\",updateChart);$(\"search\").addEventListener(\"input\",renderStockList);$(\"chatForm\").addEventListener(\"submit\",submit);$(\"ticker\").value=chosen;renderStockList();paintChat();updateChart();loadDailyMoves();\n</script></body></html>"
class handler(BaseHTTPRequestHandler):
 def do_GET(self):
  if not require_access(self):return
  body=HTML.encode("utf-8")
  self.send_response(200)
  self.send_header("Content-Type","text/html; charset=utf-8")
  self.send_header("Content-Length",str(len(body)))
  self.send_header("Cache-Control","no-store")
  self.send_header("X-Content-Type-Options","nosniff")
  self.send_header("Content-Security-Policy","default-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline' https://s3.tradingview.com; connect-src 'self'; frame-src https://www.tradingview.com https://*.tradingview.com https://s.tradingview.com https://www.tradingview-widget.com; img-src 'self' data: https:; frame-ancestors 'self'")
  self.end_headers();self.wfile.write(body)
